var builder = WebApplication.CreateBuilder(args);

builder.Services.AddOpenTelemetry()
    .WithTracing(tracing =>
    {
        tracing.AddAspNetCoreInstrumentation();
        tracing.AddHttpClientInstrumentation();
        tracing.AddEntityFrameworkCoreInstrumentation();
        tracing.AddOtlpExporter(options =>
        {
            options.Endpoint = new Uri("http://jaeger:4317");
        });
    });

var app = builder.Build();
app.MapControllers();
app.Run();

public static class OrderProcessingActivities
{
    public const string SourceName = "Quotient.Orders";
    private static readonly ActivitySource s_source = new(SourceName);

    public static ActivitySource Source => s_source;
}

public class OrderService
{
    private readonly ActivitySource _activitySource;

    public OrderService(ActivitySource activitySource)
    {
        _activitySource = activitySource;
    }

    public async Task ProcessAsync(Order order)
    {
        using var activity = _activitySource.StartActivity("ProcessOrder", ActivityKind.Internal);
        activity?.SetTag("order.id", order.Id);
        activity?.SetTag("order.items", order.Items.Count);

        await ValidateInventoryAsync(order);
        await ChargePaymentAsync(order);
        await FulfillAsync(order);
    }
}
